/**
 * Mavis Panel — Cloudflare Worker Asset & Code Compiler
 * Reads src/public/ assets, compiles worker/assets.js,
 * and generates an obfuscated production build at worker/dist/index.js.
 */

const fs = require('fs');
const path = require('path');

const ROOT_DIR = path.resolve(__dirname, '..');
const PUBLIC_DIR = path.join(ROOT_DIR, 'src', 'public');
const WORKER_DIR = path.join(ROOT_DIR, 'worker');
const DIST_DIR = path.join(WORKER_DIR, 'dist');
const ASSETS_FILE = path.join(WORKER_DIR, 'assets.js');
const SOURCE_WORKER_FILE = path.join(WORKER_DIR, 'index.js');
const DIST_WORKER_FILE = path.join(DIST_DIR, 'index.js');

if (!fs.existsSync(DIST_DIR)) {
  fs.mkdirSync(DIST_DIR, { recursive: true });
}

console.log('[BUILD:WORKER] Compiling assets for Cloudflare Worker...');

const indexHtml = fs.readFileSync(path.join(PUBLIC_DIR, 'index.html'), 'utf8');
const appCss = fs.readFileSync(path.join(PUBLIC_DIR, 'app.css'), 'utf8');
const appJs = fs.readFileSync(path.join(PUBLIC_DIR, 'app.js'), 'utf8');
const logoSvg = fs.readFileSync(path.join(PUBLIC_DIR, 'logo.svg'), 'utf8');

const assetsContent = `/**
 * Auto-generated by scripts/bundle-worker.js
 * DO NOT EDIT DIRECTLY.
 */

export const EMBEDDED_ASSETS = {
  indexHtml: ${JSON.stringify(indexHtml)},
  appCss: ${JSON.stringify(appCss)},
  appJs: ${JSON.stringify(appJs)},
  logoSvg: ${JSON.stringify(logoSvg)}
};
`;

fs.writeFileSync(ASSETS_FILE, assetsContent, 'utf8');
console.log('  -> Wrote ' + ASSETS_FILE + ' (' + (assetsContent.length / 1024).toFixed(1) + ' KB)');

// Build production bundle
let workerSource = fs.readFileSync(SOURCE_WORKER_FILE, 'utf8');
workerSource = workerSource.replace(
  "import { EMBEDDED_ASSETS } from './assets.js';",
  assetsContent.replace('export const EMBEDDED_ASSETS', 'const EMBEDDED_ASSETS')
);

try {
  const JavaScriptObfuscator = require('javascript-obfuscator');
  console.log('[BUILD:WORKER] Applying production obfuscation...');

  const obfuscated = JavaScriptObfuscator.obfuscate(workerSource, {
    compact: true,
    controlFlowFlattening: true,
    controlFlowFlatteningThreshold: 0.75,
    deadCodeInjection: false,
    debugProtection: false,
    disableConsoleOutput: false,
    identifierNamesGenerator: 'hexadecimal',
    log: false,
    numbersToExpressions: true,
    renameGlobals: false,
    selfDefending: false,
    simplify: true,
    splitStrings: true,
    splitStringsChunkLength: 5,
    stringArray: true,
    stringArrayCallsTransform: true,
    stringArrayCallsTransformThreshold: 0.75,
    stringArrayEncoding: ['base64'],
    stringArrayIndexShift: true,
    stringArrayRotate: true,
    stringArrayShuffle: true,
    stringArrayWrappersCount: 3,
    stringArrayWrappersChainedCalls: true,
    stringArrayWrappersParametersMaxCount: 4,
    stringArrayWrappersType: 'function',
    stringArrayThreshold: 1,
    target: 'browser',
    transformObjectKeys: true,
    unicodeEscapeSequence: false,
    reservedNames: ['fetch', 'connect', 'cloudflare:sockets', 'default']
  }).getObfuscatedCode();

  fs.writeFileSync(DIST_WORKER_FILE, obfuscated, 'utf8');
  console.log('  -> Wrote obfuscated bundle: ' + DIST_WORKER_FILE + ' (' + (obfuscated.length / 1024).toFixed(1) + ' KB)');
} catch (err) {
  console.warn('[BUILD:WORKER] javascript-obfuscator not found or failed, writing raw bundle:', err.message);
  fs.writeFileSync(DIST_WORKER_FILE, workerSource, 'utf8');
}
